module asyn_fifo #(
    parameter	WIDTH = 8,
    parameter 	DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);


reg [WIDTH-1:0] ram_mem[DEPTH-1:0];
reg [WIDTH-1:0] rdata_reg;
reg [3:0] waddr_bin;
reg [3:0] raddr_bin;
reg [3:0] wptr;
reg [3:0] rptr;
reg [3:0] wptr_buff;
reg [3:0] rptr_buff;
reg [3:0] wptr_syn;
reg [3:0] rptr_syn;
reg wen;
reg ren;

assign wptr = {wptr[3], wptr[3]^wptr[2], wptr[2]^wptr[1], wptr[1]^wptr[0]};

assign rptr = {rptr[3], rptr[3]^rptr[2], rptr[2]^rptr[1], rptr[1]^rptr[0]};

always @(posedge rclk or negedge rrstn) begin
    if(~rrstn) begin
        wptr_buff <= 4'd0;
    end else begin
        wptr_buff <= wptr;
    end
end

always @(posedge wclk or negedge wrstn) begin
    if(~wrstn) begin
        rptr_buff <= 4'd0;
    end else begin
        rptr_buff <= rptr;
    end
end

assign wfull = (wptr == {~rptr_buff[3], rptr_buff[2:0]});

assign rempty = (rptr == wptr_buff);

always @(posedge wclk or negedge wrstn) begin
    if(~wrstn) begin
        waddr_bin <= 4'd0;
    end else if(winc && !wfull) begin
        waddr_bin <= waddr_bin + 1;
    end
end
always @(posedge rclk or negedge rrstn) begin
    if(~rrstn) begin
        raddr_bin <= 4'd0;
    end else if(rinc && !rempty) begin
        raddr_bin <= raddr_bin + 1;
    end
end

always @(*) begin
    wen = winc && ~wfull;
    ren = rinc && ~rempty;
end

always @(posedge wclk) begin
    if(wen) begin
        ram_mem[waddr_bin] <= wdata;
    end
end

always @(posedge rclk) begin
    if(ren) begin
        rdata_reg <= ram_mem[raddr_bin];
    end
end

assign rdata = rdata_reg;

endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
